INSERT INTO website_sections (page_id,revision,section_key,kind,position,content) VALUES (@page_id,'draft','hero','hero',0,'{\"eyebrow\":\"A LITTLE CLOSER TO NATURE\",\"title\":\"Bliss nature trails\",\"description\":\"Find your natural rhythm. In emerald forests, golden wetlands and mist-covered mountains, discover a different kind of paradise.\",\"image\":\"/images/hero.webp\",\"primaryLabel\":\"Explore nature trails\",\"primaryLink\":\"#destinations\",\"secondaryLabel\":\"Plan your escape\",\"secondaryLink\":\"#experiences\"}');
INSERT INTO website_sections (page_id,revision,section_key,kind,position,content) VALUES (@page_id,'draft','nature','nature',1,'{\"items\":[{\"id\":\"forest\",\"title\":\"Forest trails\",\"description\":\"Take the path less travelled\",\"image\":\"/images/forest.webp\",\"link\":\"#destinations\",\"icon\":\"trees\"},{\"id\":\"stillness\",\"title\":\"Still waters\",\"description\":\"A little space to simply be\",\"image\":\"/images/water.webp\",\"link\":\"#story\",\"icon\":\"waves\"},{\"id\":\"wild\",\"title\":\"Wild encounters\",\"description\":\"Where wonder comes naturally\",\"image\":\"/images/wildlife.webp\",\"link\":\"#destinations\",\"icon\":\"leaf\"}]}');
INSERT INTO website_sections (page_id,revision,section_key,kind,position,content) VALUES (@page_id,'draft','story','story',2,'{\"eyebrow\":\"ROOTED IN NATURE. RICH IN LIFE.\",\"title\":\"Ancient Roots, Living Sanctuaries\",\"paragraphs\":[\"Sri Lanka is a small island with an extraordinary natural soul. From the ancient rainforests of Sinharaja to the sunlit plains of our national parks, every landscape tells a story of life, resilience and a deep connection to the earth.\",\"For centuries, nature and wellbeing have grown together here. Walk beneath the canopy of towering trees, listen to the gentle rhythm of a forest stream, and discover the quiet wisdom of a culture that has always found balance in the natural world.\",\"Responsible wildlife encounters, winding forest trails and moments of unhurried stillness. These are the experiences that stay with you, long after the journey ends.\"],\"image\":\"/images/wellness.webp\",\"cardLabel\":\"NATURALLY RESTORATIVE\",\"quote\":\"To walk these misty highland paths is to partake in the wisdom of traditional healers, where every breath whispers restorative peace.\",\"attribution\":\"Discover the art of slowing down\",\"linkLabel\":\"Explore wellness\",\"link\":\"#experiences\"}');
INSERT INTO website_sections (page_id,revision,section_key,kind,position,content) VALUES (@page_id,'draft','destinations','destinations',3,'{\"title\":\"Interactive Trail & Destination Map\",\"description\":\"Discover Sri Lanka’s most treasured places. Find a trail, follow your curiosity, and let nature lead the way.\",\"items\":[{\"id\":\"sinharaja\",\"title\":\"Sinharaja\",\"description\":\"A living rainforest, alive with birdsong and extraordinary biodiversity.\",\"category\":\"Forest reserves\",\"lat\":6.405,\"lng\":80.447,\"image\":\"/images/forest.webp\",\"location\":\"Sabaragamuwa & Southern Provinces\"},{\"id\":\"ella\",\"title\":\"Ella\",\"description\":\"Misty mountains, tea gardens and trails with unforgettable views.\",\"category\":\"Highland trails\",\"lat\":6.8667,\"lng\":81.0466,\"image\":\"/images/hero.webp\",\"location\":\"Uva Province\"},{\"id\":\"horton\",\"title\":\"Horton Plains\",\"description\":\"Follow the grasslands to the breathtaking edge of World’s End.\",\"category\":\"Highland trails\",\"lat\":6.802,\"lng\":80.807,\"image\":\"/images/hero.webp\",\"location\":\"Central Province\"},{\"id\":\"wilpattu\",\"title\":\"Wilpattu\",\"description\":\"Quiet forest tracks, natural lakes and wild encounters.\",\"category\":\"National parks\",\"lat\":8.45,\"lng\":80.05,\"image\":\"/images/wildlife.webp\",\"location\":\"North Western Province\"},{\"id\":\"minneriya\",\"title\":\"Minneriya\",\"description\":\"Discover elephant country around an ancient reservoir.\",\"category\":\"National parks\",\"lat\":8.037,\"lng\":80.903,\"image\":\"/images/wildlife.webp\",\"location\":\"North Central Province\"},{\"id\":\"knuckles\",\"title\":\"Knuckles\",\"description\":\"A spectacular mountain range woven with forest paths.\",\"category\":\"Highland trails\",\"lat\":7.45,\"lng\":80.8,\"image\":\"/images/forest.webp\",\"location\":\"Central Province\"},{\"id\":\"tangalle\",\"title\":\"Tangalle\",\"description\":\"Slow coastal mornings, lagoon life and a gentler rhythm.\",\"category\":\"Coastal escapes\",\"lat\":6.024,\"lng\":80.794,\"image\":\"/images/water.webp\",\"location\":\"Southern Province\"}]}');
